class Solution {
    public List<List<Integer>> palindromePairs(String[] words) {
        java.util.Map<String, Integer> map = new java.util.HashMap<>();
        for (int i = 0; i < words.length; i++) map.put(words[i], i);
        List<List<Integer>> result = new java.util.ArrayList<>();
        for (int i = 0; i < words.length; i++) {
            String w = words[i];
            for (int j = 0; j <= w.length(); j++) {
                String left = w.substring(0, j), right = w.substring(j);
                if (isPalindrome(left)) {
                    String revRight = new StringBuilder(right).reverse().toString();
                    if (map.containsKey(revRight) && map.get(revRight) != i) {
                        result.add(java.util.Arrays.asList(map.get(revRight), i));
                    }
                }
                if (right.length() > 0 && isPalindrome(right)) {
                    String revLeft = new StringBuilder(left).reverse().toString();
                    if (map.containsKey(revLeft) && map.get(revLeft) != i) {
                        result.add(java.util.Arrays.asList(i, map.get(revLeft)));
                    }
                }
            }
        }
        return result;
    }
    private boolean isPalindrome(String s) {
        int l = 0, r = s.length() - 1;
        while (l < r) { if (s.charAt(l++) != s.charAt(r--)) return false; }
        return true;
    }
}

import java.util.*;

class Solution {
    private int[][] children;
    private int[] wordIdx;
    private List<List<Integer>> belowPalin;
    private int trieSize;

    public List<List<Integer>> palindromePairs(String[] words) {
        int maxNodes = 1;
        for (String w : words) maxNodes += w.length();
        children = new int[maxNodes][26];
        wordIdx = new int[maxNodes];
        belowPalin = new ArrayList<>();
        for (int i = 0; i < maxNodes; i++) {
            Arrays.fill(children[i], -1);
            wordIdx[i] = -1;
            belowPalin.add(new ArrayList<>());
        }
        trieSize = 1;
        for (int i = 0; i < words.length; i++) addWord(words[i], i);
        List<List<Integer>> result = new ArrayList<>();
        for (int i = 0; i < words.length; i++) {
            String w = words[i];
            int node = 0;
            for (int j = 0; j < w.length(); j++) {
                if (wordIdx[node] >= 0 && wordIdx[node] != i && isPalin(w, j, w.length() - 1)) {
                    result.add(Arrays.asList(i, wordIdx[node]));
                }
                int c = w.charAt(j) - 'a';
                if (children[node][c] == -1) { node = -1; break; }
                node = children[node][c];
            }
            if (node == -1) continue;
            if (wordIdx[node] >= 0 && wordIdx[node] != i) {
                result.add(Arrays.asList(i, wordIdx[node]));
            }
            for (int idx : belowPalin.get(node)) {
                if (idx != i) result.add(Arrays.asList(i, idx));
            }
        }
        return result;
    }
    private void addWord(String w, int idx) {
        int node = 0;
        for (int i = w.length() - 1; i >= 0; i--) {
            if (isPalin(w, 0, i)) belowPalin.get(node).add(idx);
            int c = w.charAt(i) - 'a';
            if (children[node][c] == -1) children[node][c] = trieSize++;
            node = children[node][c];
        }
        wordIdx[node] = idx;
        belowPalin.get(node).add(idx);
    }
    private boolean isPalin(String s, int l, int r) {
        while (l < r) { if (s.charAt(l++) != s.charAt(r--)) return false; }
        return true;
    }
}
